    var config2 = {
      "previewFeatures": [],
      "clientVersion": "7.2.0",
      "engineVersion": "0c8ef2ce45c83248ab3df073180d5eda9e8be7a3",
      "activeProvider": "postgresql",
      "inlineSchema": '// prisma/schema.prisma\ndatasource db {\n  provider = "postgresql"\n}\n\ngenerator client {\n  provider = "prisma-client-js"\n}\n\nenum Status {\n  Active\n  Inactive\n}\n\nenum ShiftType {\n  Day\n  Night\n  Rotational\n}\n\nenum TodoPriority {\n  Low\n  Medium\n  High\n  Urgent\n}\n\nenum TodoStatus {\n  Open\n  InProgress\n  OnHold\n  Completed\n  Cancelled\n}\n\nenum LeadStatus {\n  New\n  Contacted\n  Interested\n  Qualified\n  Converted\n  Lost\n  OnHold\n}\n\nenum FollowUpStatus {\n  Pending\n  Completed\n  Rescheduled\n}\n\nenum EmployeeStatus {\n  Pending\n  Active\n  Inactive\n}\n\nenum CredentialApprovalStatus {\n  Pending\n  Approved\n}\n\nenum LeaveStatus {\n  Pending\n  Approved\n  Rejected\n  Cancelled\n}\n\nenum LeaveType {\n  Sick\n  Casual\n  Earned\n  Maternity\n  Paternity\n  Unpaid\n  Special\n  Bereavement\n  Marriage\n  Study\n}\n\nenum AttendanceStatus {\n  Present\n  Absent\n  Leave\n  HalfDay\n  WFH\n  Holidays\n  WeekOff\n}\n\nenum PayrollStatus {\n  Draft\n  Submitted\n  Approved\n  Processed\n  Paid\n  Rejected\n}\n\nenum PerformanceRating {\n  Outstanding\n  Exceeds\n  Meets\n  Developing\n  Unsatisfactory\n}\n\nenum GrievanceStatus {\n  Filed\n  UnderReview\n  InProgress\n  Resolved\n  Closed\n  Withdrawn\n}\n\nenum DocumentType {\n  Aadhar\n  PAN\n  DrivingLicense\n  Passport\n  EducationCertificate\n  ExperienceCertificate\n  MedicalReport\n  Other\n}\n\nmodel Employee {\n  id                     String                   @id @default(uuid())\n  name                   String\n  email                  String?                  @unique\n  phone                  String                   @unique\n  role                   String\n  department             String\n  status                 EmployeeStatus           @default(Pending)\n  approvedForCredentials CredentialApprovalStatus @default(Pending)\n\n  dateOfJoining         DateTime?\n  dateOfBirth           DateTime?\n  ctc                   Float?\n  baseSalary            Float?\n  fatherName            String?\n  motherName            String?\n  spouseName            String?\n  permanentAddress      String?\n  currentAddress        String?\n  bloodGroup            String?\n  emergencyContact      String?\n  emergencyContactPhone String?\n\n  // HR Extended Fields\n  designation        String?\n  reportingManagerId String?\n  reportingManager   Employee?  @relation("ReportingManager", fields: [reportingManagerId], references: [id])\n  subordinates       Employee[] @relation("ReportingManager")\n  bankName           String?\n  bankAccountNumber  String?\n  bankIfscCode       String?\n  panNumber          String?\n  aadharNumber       String?\n  esi                String?\n  pf                 String?\n  totalLeaveBalance  Int?       @default(0)\n  usedLeave          Int?       @default(0)\n\n  createdByRole   String\n  username        String?   @unique\n  password        String?\n  approvedBy      String?\n  approvedAt      DateTime?\n  rejectionReason String?\n  refreshToken    String?\n\n  createdTodos       Todo[]         @relation("CreatedTodos")\n  assignedTodos      Todo[]         @relation("AssignedTodos")\n  mentionedInTodos   TodoMention[]  @relation("MentionedEmployee")\n  assignedLeads      Lead[]         @relation("AssignedLeads")\n  adminAssignedLeads Lead[]         @relation("AdminAssignedLeads")\n  leadFollowUps      LeadFollowUp[] @relation("LeadFollowUps")\n\n  // Customer Assignment Relations\n  createdCustomers        Customer[]                  @relation("CustomerCreatedBy")\n  assignedCustomers       Customer[]                  @relation("CustomerAssignedTo")\n  customerAssignmentsByMe CustomerAssignmentHistory[] @relation("CustomerAssignedBy")\n\n  // Purchase Order Assignment Relations\n  assignedPurchaseOrders PurchaseOrder[]                  @relation("PurchaseOrderAssignedTo")\n  poAssignmentsByMe      PurchaseOrderAssignmentHistory[] @relation("PurchaseOrderAssignedBy")\n\n  // HR Relations\n  leaveRequests         LeaveRequest[]      @relation("EmployeeLeaveRequests")\n  approverLeaveRequests LeaveRequest[]      @relation("ApproverLeaveRequests")\n  attendanceRecords     Attendance[]\n  payrollRecords        Payroll[]\n  documents             EmployeeDocument[]\n  performanceReviews    PerformanceReview[] @relation("RevieweePerformance")\n  givenReviews          PerformanceReview[] @relation("ReviewerPerformance")\n  employeeBenefits      EmployeeBenefit[]\n  grievances            Grievance[]         @relation("EmployeeGrievance")\n  grievanceAssignedTo   Grievance[]         @relation("AssignedToGrievance")\n  shifts                EmployeeShift[]\n  trainingPrograms      EmployeeTraining[]\n\n  // Security Relations\n  loginAttempts     LoginAttempt[]     @relation("LoginAttempts")\n  accountLockouts   AccountLockout[]   @relation("AccountLockouts")\n  securityAuditLogs SecurityAuditLog[] @relation("SecurityAuditLogs")\n  navbarPermissions NavbarPermission?  @relation("NavbarPermissions")\n\n  // Login Access Control\n  canLogin Boolean @default(true)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([department])\n  @@index([status])\n  @@index([reportingManagerId])\n}\n\nmodel Customer {\n  id                   String                      @id @default(uuid())\n  customerName         String\n  address              String?\n  creditLimit          Float                       @default(0)\n  creditApprovalStatus String                      @default("Pending")\n  paymentTerms         String\n  throughVia           String?\n  gstrNo               String                      @unique\n  createdByEmployeeId  String?\n  createdByEmployee    Employee?                   @relation("CustomerCreatedBy", fields: [createdByEmployeeId], references: [id])\n  assignedToEmployeeId String?\n  assignedToEmployee   Employee?                   @relation("CustomerAssignedTo", fields: [assignedToEmployeeId], references: [id])\n  assignedAt           DateTime?\n  kycProfile           String?\n  contactName          String?\n  contactPhone         String?\n  contactEmail         String?\n  contacts             Json?\n  remarks              String?\n  relationshipStatus   String?\n  gstCopy              String?\n  drugLicense          String? // License number (string)\n  dlExpiry             DateTime? // Expiry date (DateTime)\n  isBlacklisted        Boolean                     @default(false)\n  blacklistReason      String?\n  promotor             String?\n  blacklistedAt        DateTime?\n  purchaseOrders       PurchaseOrder[]\n  leads                Lead[]\n  annualTurnover       String?\n  assignmentHistory    CustomerAssignmentHistory[]\n  createdAt            DateTime                    @default(now())\n  updatedAt            DateTime                    @updatedAt\n}\n\nmodel CustomerAssignmentHistory {\n  id                   String   @id @default(uuid())\n  customerId           String\n  customer             Customer @relation(fields: [customerId], references: [id], onDelete: Cascade)\n  assignedToEmployeeId String?\n  assignedByEmployeeId String\n  assignedByEmployee   Employee @relation("CustomerAssignedBy", fields: [assignedByEmployeeId], references: [id])\n  previousEmployeeId   String?\n  reason               String?\n  remarks              String?\n  assignedAt           DateTime @default(now())\n\n  @@index([customerId])\n  @@index([assignedToEmployeeId])\n  @@index([assignedAt])\n}\n\nmodel Lead {\n  id                   String         @id @default(uuid())\n  customerId           String\n  customer             Customer       @relation(fields: [customerId], references: [id], onDelete: Cascade)\n  assignedToEmployeeId String?\n  assignedToEmployee   Employee?      @relation("AssignedLeads", fields: [assignedToEmployeeId], references: [id])\n  assignedByEmployeeId String\n  assignedByEmployee   Employee       @relation("AdminAssignedLeads", fields: [assignedByEmployeeId], references: [id])\n  status               LeadStatus     @default(New)\n  followUps            LeadFollowUp[]\n  notes                String?\n  assignedAt           DateTime       @default(now())\n  lastContactedAt      DateTime?\n  createdAt            DateTime       @default(now())\n  updatedAt            DateTime       @updatedAt\n\n  assignmentHistory LeadAssignmentHistory[]\n\n  @@unique([customerId, assignedToEmployeeId])\n}\n\nmodel LeadAssignmentHistory {\n  id                   String   @id @default(uuid())\n  leadId               String\n  lead                 Lead     @relation(fields: [leadId], references: [id], onDelete: Cascade)\n  assignedToEmployeeId String?\n  assignedByEmployeeId String\n  assignedAt           DateTime @default(now())\n  notes                String?\n}\n\nmodel LeadFollowUp {\n  id               String         @id @default(uuid())\n  leadId           String\n  lead             Lead           @relation(fields: [leadId], references: [id], onDelete: Cascade)\n  employeeId       String\n  employee         Employee       @relation("LeadFollowUps", fields: [employeeId], references: [id])\n  followUpType     String // e.g., "Call", "Email", "Meeting", "Demo"\n  notes            String?\n  nextFollowUpDate DateTime?\n  status           FollowUpStatus @default(Pending)\n  createdAt        DateTime       @default(now())\n  updatedAt        DateTime       @updatedAt\n}\n\nmodel Todo {\n  id                 String        @id @default(uuid())\n  title              String\n  description        String?\n  priority           TodoPriority  @default(Medium)\n  status             TodoStatus    @default(Open)\n  createdById        String\n  createdBy          Employee      @relation("CreatedTodos", fields: [createdById], references: [id], onDelete: Cascade)\n  assignedToId       String?\n  assignedTo         Employee?     @relation("AssignedTodos", fields: [assignedToId], references: [id], onDelete: SetNull)\n  mentionedEmployees TodoMention[] @relation("TodoMentions")\n  updates            TodoUpdate[]  @relation("TodoUpdates")\n  completed          Boolean       @default(false)\n  completedAt        DateTime?\n  dueDate            DateTime?\n  createdAt          DateTime      @default(now())\n  updatedAt          DateTime      @updatedAt\n\n  @@index([createdById])\n  @@index([assignedToId])\n  @@index([priority])\n  @@index([dueDate])\n  @@index([completed])\n  @@index([status])\n}\n\nmodel TodoMention {\n  id          String   @id @default(uuid())\n  todoId      String\n  todo        Todo     @relation("TodoMentions", fields: [todoId], references: [id], onDelete: Cascade)\n  employeeId  String\n  employee    Employee @relation("MentionedEmployee", fields: [employeeId], references: [id], onDelete: Cascade)\n  mentionedAt DateTime @default(now())\n\n  @@unique([todoId, employeeId])\n  @@index([employeeId])\n  @@index([todoId])\n}\n\nmodel TodoUpdate {\n  id          String   @id @default(uuid())\n  todoId      String\n  todo        Todo     @relation("TodoUpdates", fields: [todoId], references: [id], onDelete: Cascade)\n  description String\n  updateType  String // "comment", "status_change", "assignment", "mention_added", "mention_removed"\n  oldValue    String?\n  newValue    String?\n  createdAt   DateTime @default(now())\n\n  @@index([todoId])\n  @@index([createdAt])\n}\n\nmodel PurchaseOrder {\n  id                          String    @id @default(uuid())\n  gstNo                       String?\n  customerId                  String?\n  customer                    Customer? @relation(fields: [customerId], references: [id])\n  assignedToEmployeeId        String?\n  assignedToEmployee          Employee? @relation("PurchaseOrderAssignedTo", fields: [assignedToEmployeeId], references: [id])\n  assignedAt                  DateTime?\n  poNo                        String?   @default(uuid())\n  poDate                      DateTime?\n  dispatchDate                DateTime?\n  brandName                   String?\n  partyName                   String?\n  batchNo                     String?\n  paymentTerms                String?\n  invCha                      String?\n  cylChar                     String?\n  orderThrough                String?\n  address                     String?\n  composition                 String?\n  notes                       String?\n  rmStatus                    String?\n  poQty                       String?\n  poRate                      String?\n  amount                      String?\n  mrp                         String?\n  section                     String?\n  specialRequirements         String?\n  tabletCapsuleDrySyrupBottle String?\n  roundOvalTablet             String?\n  tabletColour                String?\n  aluAluBlisterStripBottle    String?\n  packStyle                   String?\n  productNewOld               String?\n  qaObservations              String?\n  batchQty                    String?\n  expiry                      DateTime?\n  pvcColourBase               String?\n  foil                        String?\n  lotNo                       String?\n  foilPoDate                  DateTime?\n  foilSize                    String?\n  foilPoVendor                String?\n  foilBillDate                DateTime?\n  foilQuantity                String?\n  cartonPoDate                DateTime?\n  cartonPoVendor              String?\n  cartonBillDate              DateTime?\n  cartonQuantity              String?\n  packingDate                 DateTime?\n  qtyPacked                   String?\n  noOfShippers                String?\n  design                      String?\n  productionStatus            String? // Status during production/manufacturing\n  overallStatus               String    @default("Pending")\n  invoiceNo                   String?\n  invoiceDate                 DateTime?\n  changePart                  String?\n  cyc                         String?\n  advance                     String?\n  showStatus                  String    @default("Order Pending")\n  mdApproval                  String    @default("Pending")\n  accountsApproval            String    @default("Pending")\n  designerApproval            String    @default("Pending")\n  ppicApproval                String    @default("Pending")\n  designerActions             Json?\n  accountBills                Json?\n  salesComments               String?\n  poDisputes                  Json?\n  rawImportedData             Json? // JSON field for unmapped sheet columns\n\n  // NEW FIELDS\n  foilQuantityOrdered   String?\n  cartonQuantityOrdered String?\n  dispatchStatus        String?                          @default("Pending")\n  timestamp             Json? // JSON field for RM / Production / Dispatch statuses + timestamps\n  statusHistory         PurchaseOrderStatusHistory[]\n  assignmentHistory     PurchaseOrderAssignmentHistory[]\n  createdAt             DateTime                         @default(now())\n  updatedAt             DateTime                         @updatedAt\n\n  @@index([gstNo])\n  @@index([customerId])\n  @@index([assignedToEmployeeId])\n  @@index([poDate])\n  @@index([overallStatus])\n  @@index([createdAt])\n}\n\nmodel PurchaseOrderStatusHistory {\n  id String @id @default(uuid())\n\n  purchaseOrderId String\n  purchaseOrder   PurchaseOrder @relation(fields: [purchaseOrderId], references: [id], onDelete: Cascade)\n\n  status    String\n  remarks   String?\n  changedBy String?\n  metadata  Json?\n\n  createdAt DateTime @default(now())\n\n  @@index([purchaseOrderId])\n  @@index([status])\n}\n\nmodel PurchaseOrderAssignmentHistory {\n  id                   String        @id @default(uuid())\n  purchaseOrderId      String\n  purchaseOrder        PurchaseOrder @relation(fields: [purchaseOrderId], references: [id], onDelete: Cascade)\n  assignedToEmployeeId String?\n  assignedByEmployeeId String\n  assignedByEmployee   Employee      @relation("PurchaseOrderAssignedBy", fields: [assignedByEmployeeId], references: [id])\n  previousEmployeeId   String?\n  reason               String?\n  remarks              String?\n  assignedAt           DateTime      @default(now())\n\n  @@index([purchaseOrderId])\n  @@index([assignedToEmployeeId])\n  @@index([assignedAt])\n}\n\nmodel Notification {\n  id        String   @id @default(uuid())\n  userId    String\n  type      String\n  message   String\n  isRead    Boolean  @default(false)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\nmodel AuditLog {\n  id          String   @id @default(uuid())\n  action      String\n  performedBy String\n  targetId    String\n  details     Json?\n  timestamp   DateTime @default(now())\n\n  @@map("audit_logs")\n}\n\nmodel ChangePartMaster {\n  id                     String   @id @default(uuid())\n  partPictureUrl         String?\n  code                   String?\n  boxSizeAutoCalculated  String?\n  cartonRates            Decimal?\n  baseFoilConsumption    Decimal?\n  printedFoilConsumption Decimal?\n  tabSize                String?\n  range                  String?\n  foilSize               String?\n  createdAt              DateTime @default(now())\n  updatedAt              DateTime @updatedAt\n}\n\nmodel CompositionMaster {\n  id                String   @id @default(uuid())\n  composition       String?\n  formType          String?\n  packingType       String?\n  layerType         String?\n  color             String?\n  flavor            String?\n  coating           String?\n  changePartOptions String[] @default([]) // fixed\n  shelfLifeMonths   Int?\n  review            String?\n  createdAt         DateTime @default(now())\n  updatedAt         DateTime @updatedAt\n}\n\nmodel ApiMaster {\n  id           String   @id @default(uuid())\n  drugName     String\n  drugQuantity String?\n  createdAt    DateTime @default(now())\n  updatedAt    DateTime @updatedAt\n}\n\nmodel VendorMaster {\n  id                  String   @id @default(uuid())\n  vendorName          String\n  vendorCode          String?\n  contactPerson       String?\n  vendorEmail         String?\n  vendorPhone         String?\n  vendorAdress        String?\n  vendorState         String?\n  vendorGSTNo         String?\n  paymentTerms        String?\n  vendorBankName      String?\n  vendorAccountNumber String?\n  vendorIFSC          String?\n  createdAt           DateTime @default(now())\n  updatedAt           DateTime @updatedAt\n}\n\n// ============ HR MODULE MODELS ============\n\nmodel LeaveRequest {\n  id                 String      @id @default(uuid())\n  employeeId         String\n  employee           Employee    @relation("EmployeeLeaveRequests", fields: [employeeId], references: [id], onDelete: Cascade)\n  leaveType          LeaveType\n  startDate          DateTime\n  endDate            DateTime\n  numberOfDays       Int\n  requestedBy        String?\n  reason             String?\n  status             LeaveStatus @default(Pending)\n  approverEmployeeId String?\n  approverEmployee   Employee?   @relation("ApproverLeaveRequests", fields: [approverEmployeeId], references: [id], onDelete: SetNull)\n  approverComments   String?\n  approvedAt         DateTime?\n  rejectedAt         DateTime?\n  rejectionReason    String?\n  attachmentUrl      String?\n  createdAt          DateTime    @default(now())\n  updatedAt          DateTime    @updatedAt\n\n  @@index([employeeId])\n  @@index([status])\n  @@index([startDate])\n  @@index([leaveType])\n}\n\nmodel Attendance {\n  id             String           @id @default(uuid())\n  employeeId     String\n  employee       Employee         @relation(fields: [employeeId], references: [id], onDelete: Cascade)\n  attendanceDate DateTime\n  status         AttendanceStatus @default(Absent)\n  checkInTime    DateTime?\n  checkOutTime   DateTime?\n  workingHours   Float?\n  location       String?\n  notes          String?\n  deviceId       String?\n  verifiedBy     String?\n  createdAt      DateTime         @default(now())\n  updatedAt      DateTime         @updatedAt\n\n  @@unique([employeeId, attendanceDate])\n  @@index([employeeId])\n  @@index([attendanceDate])\n  @@index([status])\n}\n\nmodel Payroll {\n  id                  String   @id @default(uuid())\n  employeeId          String\n  employee            Employee @relation(fields: [employeeId], references: [id], onDelete: Cascade)\n  payrollMonth        DateTime\n  baseSalary          Float\n  housRentAllowance   Float    @default(0)\n  conveyanceAllowance Float    @default(0)\n  medicalAllowance    Float    @default(0)\n  specialAllowance    Float    @default(0)\n  bonus               Float    @default(0)\n  otherAdditions      Float    @default(0)\n  totalAdditions      Float\n\n  incomeTax              Float @default(0)\n  providentFund          Float @default(0)\n  employeeStateInsurance Float @default(0)\n  otherDeductions        Float @default(0)\n  totalDeductions        Float\n\n  netSalary  Float\n  status     PayrollStatus @default(Draft)\n  approvedBy String?\n  approvedAt DateTime?\n  remarks    String?\n  pdfUrl     String?\n  createdAt  DateTime      @default(now())\n  updatedAt  DateTime      @updatedAt\n\n  @@index([employeeId])\n  @@index([payrollMonth])\n  @@index([status])\n}\n\nmodel EmployeeDocument {\n  id                 String       @id @default(uuid())\n  employeeId         String\n  employee           Employee     @relation(fields: [employeeId], references: [id], onDelete: Cascade)\n  documentType       DocumentType\n  documentName       String\n  documentNumber     String?\n  fileUrl            String\n  expiryDate         DateTime?\n  issueDate          DateTime?\n  issuingAuthority   String?\n  extractedData      Json? // Stores PDF extracted data\n  verificationStatus String       @default("Pending")\n  verifiedBy         String?\n  verifiedAt         DateTime?\n  remarks            String?\n  createdAt          DateTime     @default(now())\n  updatedAt          DateTime     @updatedAt\n\n  @@index([employeeId])\n  @@index([documentType])\n  @@index([verificationStatus])\n}\n\nmodel PerformanceReview {\n  id                String            @id @default(uuid())\n  revieweeId        String\n  reviewee          Employee          @relation("RevieweePerformance", fields: [revieweeId], references: [id], onDelete: Cascade)\n  reviewerId        String\n  reviewer          Employee          @relation("ReviewerPerformance", fields: [reviewerId], references: [id], onDelete: SetNull)\n  reviewPeriodStart DateTime\n  reviewPeriodEnd   DateTime\n  overallRating     PerformanceRating\n\n  // Performance Criteria Ratings\n  technicalSkills PerformanceRating?\n  communication   PerformanceRating?\n  teamwork        PerformanceRating?\n  leadership      PerformanceRating?\n  reliability     PerformanceRating?\n  innovation      PerformanceRating?\n\n  achievements       String?\n  areasOfImprovement String?\n  feedback           String?\n  goals              String?\n  developmentPlan    String?\n\n  acknowledgedAt DateTime?\n  createdAt      DateTime  @default(now())\n  updatedAt      DateTime  @updatedAt\n\n  @@index([revieweeId])\n  @@index([reviewerId])\n  @@index([reviewPeriodStart])\n}\n\nmodel EmployeeBenefit {\n  id                 String    @id @default(uuid())\n  employeeId         String\n  employee           Employee  @relation(fields: [employeeId], references: [id], onDelete: Cascade)\n  benefitName        String\n  benefitDescription String?\n  benefitType        String // Health, Retirement, Insurance, etc.\n  enrollmentDate     DateTime\n  expiryDate         DateTime?\n  benefitAmount      Float?\n  provider           String?\n  policyNumber       String?\n  documentUrl        String?\n  status             String    @default("Active")\n  createdAt          DateTime  @default(now())\n  updatedAt          DateTime  @updatedAt\n\n  @@index([employeeId])\n  @@index([benefitType])\n}\n\nmodel Grievance {\n  id             String          @id @default(uuid())\n  employeeId     String\n  employee       Employee        @relation("EmployeeGrievance", fields: [employeeId], references: [id], onDelete: Cascade)\n  grievanceType  String // Harassment, Discrimination, Unfair Treatment, etc.\n  description    String\n  dateOfIncident DateTime\n  submittedDate  DateTime        @default(now())\n  status         GrievanceStatus @default(Filed)\n  assignedToId   String?\n  assignedTo     Employee?       @relation("AssignedToGrievance", fields: [assignedToId], references: [id], onDelete: SetNull)\n\n  investigationNotes String?\n  resolution         String?\n  resolutionDate     DateTime?\n  followUpRequired   Boolean   @default(false)\n  followUpDate       DateTime?\n\n  attachments Json? // Array of attachment URLs\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  @@index([employeeId])\n  @@index([status])\n  @@index([grievanceType])\n}\n\nmodel EmployeeShift {\n  id              String    @id @default(uuid())\n  employeeId      String\n  employee        Employee  @relation(fields: [employeeId], references: [id], onDelete: Cascade)\n  shiftType       ShiftType @default(Day)\n  startTime       DateTime?\n  endTime         DateTime?\n  effectiveFrom   DateTime\n  effectiveUntil  DateTime?\n  breakDuration   Int? // in minutes\n  rotationPattern String? // Weekly, Bi-weekly, Monthly\n  createdAt       DateTime  @default(now())\n  updatedAt       DateTime  @updatedAt\n\n  @@index([employeeId])\n  @@index([shiftType])\n}\n\nmodel EmployeeTraining {\n  id               String    @id @default(uuid())\n  employeeId       String\n  employee         Employee  @relation(fields: [employeeId], references: [id], onDelete: Cascade)\n  trainingName     String\n  trainingProvider String?\n  startDate        DateTime\n  endDate          DateTime?\n  duration         Int? // in hours\n  skillsAcquired   String?\n  certificateUrl   String?\n  cost             Float?\n  status           String    @default("Scheduled")\n  completionDate   DateTime?\n  assessmentScore  Float?\n  createdAt        DateTime  @default(now())\n  updatedAt        DateTime  @updatedAt\n\n  @@index([employeeId])\n  @@index([startDate])\n}\n\nmodel Designation {\n  id              String   @id @default(uuid())\n  name            String   @unique\n  description     String?\n  department      String\n  reportingTo     String?\n  baseSalaryRange String?\n  skills          String[] @default([])\n  status          String   @default("Active")\n  createdAt       DateTime @default(now())\n  updatedAt       DateTime @updatedAt\n\n  @@index([department])\n}\n\nmodel Department {\n  id               String   @id @default(uuid())\n  name             String   @unique\n  code             String?  @unique\n  description      String?\n  headOfDepartment String?\n  budget           Float?\n  status           String   @default("Active")\n  createdAt        DateTime @default(now())\n  updatedAt        DateTime @updatedAt\n}\n\n// ============ SECURITY & LOGIN TRACKING ============\n\nenum LoginAttemptStatus {\n  Success\n  Failed\n  Blocked\n}\n\nmodel LoginAttempt {\n  id            String             @id @default(uuid())\n  username      String // Username attempted to login\n  email         String? // Employee email if found\n  employeeId    String? // Employee ID if successful\n  employee      Employee?          @relation("LoginAttempts", fields: [employeeId], references: [id], onDelete: SetNull)\n  ipAddress     String // IP address of the attempt\n  userAgent     String? // Browser/device information\n  status        LoginAttemptStatus @default(Failed)\n  failureReason String? // Why login failed (wrong password, account locked, etc)\n  deviceInfo    Json? // Stored device fingerprint/info\n  location      String? // Geo-location if available\n  latitude      Float?\n  longitude     Float?\n  timestamp     DateTime           @default(now())\n  sessionId     String? // Session ID if successful\n\n  @@index([username])\n  @@index([employeeId])\n  @@index([ipAddress])\n  @@index([status])\n  @@index([timestamp])\n  @@index([email])\n}\n\nmodel BlockedIP {\n  id           String    @id @default(uuid())\n  ipAddress    String    @unique\n  reason       String? // Why the IP was blocked\n  blockedBy    String // Admin who blocked it\n  autoBlocked  Boolean   @default(false) // Whether it was auto-blocked by system\n  attemptCount Int       @default(0) // Number of failed attempts before blocking\n  blockedAt    DateTime  @default(now())\n  unblockedAt  DateTime?\n  isActive     Boolean   @default(true)\n  notes        String?\n\n  @@index([ipAddress])\n  @@index([isActive])\n  @@index([blockedAt])\n}\n\nmodel SecurityPolicy {\n  id                            String   @id @default(uuid())\n  name                          String   @unique\n  maxLoginAttemptsPerIp         Int      @default(5) // Max failed attempts per IP before blocking\n  maxLoginAttemptsPerUsername   Int      @default(10) // Max failed attempts per username before locking account\n  loginAttemptWindowMinutes     Int      @default(15) // Time window for counting attempts\n  accountLockoutDurationMinutes Int      @default(30) // Duration account remains locked after max attempts\n  ipBlockDurationMinutes        Int      @default(60) // Duration IP remains blocked after max attempts\n  requireMfa                    Boolean  @default(false) // Multi-factor authentication\n  requireStrongPassword         Boolean  @default(true)\n  passwordMinLength             Int      @default(8)\n  passwordRequireNumbers        Boolean  @default(true)\n  passwordRequireSpecialChars   Boolean  @default(true)\n  passwordRequireUpperCase      Boolean  @default(true)\n  passwordExpiryDays            Int      @default(90)\n  sessionTimeoutMinutes         Int      @default(30)\n  enableIpWhitelisting          Boolean  @default(false)\n  enableGeoRestriction          Boolean  @default(false)\n  allowedCountries              String[] @default([]) // ISO country codes\n  suspiciousActivityAlert       Boolean  @default(true)\n  logAllAttempts                Boolean  @default(true)\n  enableAnomalyDetection        Boolean  @default(true)\n  createdAt                     DateTime @default(now())\n  updatedAt                     DateTime @updatedAt\n\n  @@index([name])\n}\n\nmodel AccountLockout {\n  id             String    @id @default(uuid())\n  employeeId     String    @unique\n  employee       Employee? @relation("AccountLockouts", fields: [employeeId], references: [id], onDelete: Cascade)\n  lockedAt       DateTime  @default(now())\n  lockedUntil    DateTime\n  reason         String // Reason for lockout\n  failedAttempts Int // Number of failed attempts\n  unlockToken    String? // Token to unlock account via email\n  unlockedAt     DateTime?\n  unlockedBy     String? // Admin who unlocked or "auto" if self-unlocked\n\n  @@index([employeeId])\n  @@index([lockedUntil])\n  @@index([unlockedAt])\n}\n\nmodel SecurityAuditLog {\n  id          String    @id @default(uuid())\n  employeeId  String? // Employee involved (if applicable)\n  employee    Employee? @relation("SecurityAuditLogs", fields: [employeeId], references: [id], onDelete: SetNull)\n  action      String // LOGIN_ATTEMPT, IP_BLOCKED, ACCOUNT_LOCKED, MFA_ENABLED, etc\n  ipAddress   String?\n  userAgent   String?\n  severity    String    @default("Info") // Info, Warning, Critical\n  description String\n  metadata    Json? // Additional info about the event\n  timestamp   DateTime  @default(now())\n\n  @@index([employeeId])\n  @@index([action])\n  @@index([severity])\n  @@index([timestamp])\n  @@index([ipAddress])\n}\n\nmodel NavbarPermission {\n  id               String   @id @default(uuid())\n  employeeId       String   @unique\n  employee         Employee @relation("NavbarPermissions", fields: [employeeId], references: [id], onDelete: Cascade)\n  employeeName     String\n  email            String\n  allowedMenuItems String[] // Array of menu item IDs/names\n  createdAt        DateTime @default(now())\n  updatedAt        DateTime @updatedAt\n\n  @@index([employeeId])\n  @@index([createdAt])\n}\n'
    };
