// src/modules/hr/attendance/attendance.service.ts
init_postgres();
var attendanceService = {
  async recordAttendance(data, performedBy) {
    try {
      const attendanceDate = new Date(data.attendanceDate);
      attendanceDate.setHours(0, 0, 0, 0);
      const existing = await postgres_default.attendance.findUnique({
        where: {
          employeeId_attendanceDate: {
            employeeId: data.employeeId,
            attendanceDate
          }
        }
      });
      if (existing) {
        throw new Error("Attendance record already exists for this date");
      }
      const attendance = await postgres_default.attendance.create({
        data: {
          ...data,
          attendanceDate
        },
        include: {
          employee: {
            select: {
              id: true,
              name: true,
              email: true,
              department: true
            }
          }
        }
      });
      await logAction({
        action: "CREATE_ATTENDANCE",
        performedBy: performedBy || "SYSTEM",
        targetId: attendance.id,
        details: {
          employeeId: data.employeeId,
          status: data.status,
          attendanceDate
        }
      });
      logger.info(`Attendance recorded: ${attendance.id}`);
      return attendance;
    } catch (error48) {
      logger.error("Error recording attendance:", error48);
      throw error48;
    }
  },
  async updateAttendance(id, data) {
    try {
      const attendance = await postgres_default.attendance.update({
        where: { id },
        data,
        include: {
          employee: {
            select: {
              id: true,
              name: true,
              email: true
            }
          }
        }
      });
      await logAction({
        action: "UPDATE_ATTENDANCE",
        performedBy: data.performedBy || "SYSTEM",
        targetId: id,
        details: data
      });
      logger.info(`Attendance updated: ${id}`);
      return attendance;
    } catch (error48) {
      logger.error("Error updating attendance:", error48);
      throw error48;
    }
  },
  async getAttendanceReport(query) {
    try {
      const { employeeId, month, year, skip: skip2 = 0, take = 100 } = query;
      const whereClause = {};
      if (employeeId) whereClause.employeeId = employeeId;
      if (month && year) {
        const startDate = new Date(year, month - 1, 1);
        const endDate = new Date(year, month, 0);
        whereClause.attendanceDate = {
          $gte: startDate,
          $lte: endDate
        };
      }
      const [records, total] = await Promise.all([
        postgres_default.attendance.findMany({
          where: whereClause,
          include: {
            employee: {
              select: {
                id: true,
                name: true,
                email: true,
                department: true
              }
            }
          },
          skip: skip2,
          take,
          orderBy: { attendanceDate: "desc" }
        }),
        postgres_default.attendance.count({ where: whereClause })
      ]);
      const presentDays = records.filter((r) => r.status === "Present").length;
      const absentDays = records.filter((r) => r.status === "Absent").length;
      const leaveDays = records.filter((r) => r.status === "Leave").length;
      return {
        records,
        summary: {
          presentDays,
          absentDays,
          leaveDays,
          totalWorkingDays: records.length
        },
        total,
        pages: Math.ceil(total / take)
      };
    } catch (error48) {
      logger.error("Error fetching attendance report:", error48);
      throw error48;
    }
  },
  async bulkImportAttendance(data) {
    try {
      const results = [];
      for (const record2 of data) {
        try {
          const attendance = await this.recordAttendance(record2);
          results.push({ success: true, data: attendance });
        } catch (error48) {
          results.push({ success: false, error: error48.message, record: record2 });
        }
      }
      return results;
    } catch (error48) {
      logger.error("Error bulk importing attendance:", error48);
      throw error48;
    }
  }
};

